#!/usr/bin/env node
/**
 * One process, one reservation attempt. Used by the multi-process locking
 * test: mutual exclusion across PROCESSES cannot be tested inside a single
 * event loop, which is what let the previous racy lock look correct.
 *
 * Prints OK when the reservation was granted, REFUSED when the cap rejected
 * it. Any other output is a bug.
 */
import { reserveDailySpend } from '../dist/spend-ledger.js';

const [cap, amount] = process.argv.slice(2);
const account = {
  name: 'alice',
  address: '0x0000000000000000000000000000000000000001',
  network: 'sepolia',
  createdAt: '2026-01-01T00:00:00.000Z',
  dailySpendCap: cap,
};

try {
  await reserveDailySpend(account, BigInt(amount));
  process.stdout.write('OK');
} catch (err) {
  process.stdout.write(
    String(err.message).includes('cap exceeded') ? 'REFUSED' : `ERR:${err.message}`,
  );
}
